using Bom.Unity;
using UnityEngine;
static class Program {
 static void Check(bool value,string text){if(!value)throw new Exception(text);}
 static BomClipSource Source(Vector2[] outline,float depth=1,Vector2 offset=default){
  var data=BomExtrusion.BuildData(outline,depth,offset);var triangles=new List<BomClipTriangle>();
  BomClipVertex Vertex(int i)=>new BomClipVertex{Position=data.Vertices[i],Normal=data.Normals[i],Tangent=new Vector4(1,0,0,1),Color=new Color((data.Vertices[i].x+2)/4,(data.Vertices[i].y+2)/4,.5f,1),UV0=new Vector4(data.UV[i].x,data.UV[i].y,0,0),UV1=new Vector4(data.Vertices[i].x,data.Vertices[i].y,data.Vertices[i].z,1),UV2=new Vector4(data.Vertices[i].x*2,data.Vertices[i].y*2,data.Vertices[i].z*2,2),UV7=new Vector4(data.Vertices[i].x*7,data.Vertices[i].y*7,data.Vertices[i].z*7,7)};
  void Add(int[] indices,int material){for(int i=0;i<indices.Length;i+=3)triangles.Add(new BomClipTriangle(Vertex(indices[i]),Vertex(indices[i+1]),Vertex(indices[i+2]),material));}
  Add(data.Faces,0);Add(data.Sides,1);var source=BomPrismClipper.Prepare(triangles.ToArray(),2);Check(source.Failure==null,"source: "+source.Failure);return source;
 }
 static double Volume(BomClipResult result){double volume=0;void Add(BomClipTriangle t){volume+=Vector3.Dot(t.A.Position,Vector3.Cross(t.B.Position,t.C.Position))/6.0;}foreach(var t in result.Exterior)Add(t);foreach(var cap in result.Caps)if(!cap.DecompositionInterior)foreach(var t in cap.Triangles)Add(t);return volume;}
 static void More(){
  var a=Source(new[]{new Vector2(-2,-1),new Vector2(-1,-1),new Vector2(-1,1),new Vector2(-2,1)});var b=Source(new[]{new Vector2(1,-1),new Vector2(2,-1),new Vector2(2,1),new Vector2(1,1)});
  var combined=new List<BomClipTriangle>(a.Triangles);combined.AddRange(b.Triangles);var collection=BomPrismClipper.Prepare(combined.ToArray(),2);Check(collection.Failure==null,"disconnected preflight");var disconnected=BomPrismClipper.Build(collection,new[]{new Vector2(-3,0),new Vector2(3,0),new Vector2(3,2),new Vector2(-3,2)});Check(disconnected.Supported,"multi-mesh collection: "+disconnected.Reason);Check(Math.Abs(Volume(disconnected)-2)<.0001,"disconnected volume");Console.WriteLine("PASS disconnected multi-solid group volume="+Volume(disconnected));
  var coincident=BomPrismClipper.Build(a,new[]{new Vector2(-2,-1),new Vector2(-1,-1),new Vector2(-1,1),new Vector2(-2,1)});Check(coincident.Supported&&coincident.Caps.Length==0&&Math.Abs(Volume(coincident)-2)<.0001,"coincident original surfaces must not gain duplicate caps");Console.WriteLine("PASS coincident-plane original surface ownership");
  var inward=new List<BomClipTriangle>(a.Triangles);foreach(var t in b.Triangles)inward.Add(new BomClipTriangle(t.C,t.B,t.A,t.Material));Check(BomPrismClipper.Prepare(inward.ToArray(),2).Failure!=null,"inward component hidden by a larger outward component");Console.WriteLine("PASS inward disconnected component explicit fallback");
  BomClipVertex Mirror(BomClipVertex v){v.Position=new Vector3(7-2*v.Position.x,-2+3*v.Position.y,4+.4f*v.Position.z);v.Normal=new Vector3(-v.Normal.x/2,v.Normal.y/3,v.Normal.z/.4f).normalized;v.Tangent=new Vector4(-1,0,0,-1);return v;}
  var original=Source(new[]{new Vector2(-1,-1),new Vector2(1,-1),new Vector2(1,1),new Vector2(-1,1)},1,new Vector2(8,2));var mirrored=new List<BomClipTriangle>();foreach(var t in original.Triangles)mirrored.Add(new BomClipTriangle(Mirror(t.C),Mirror(t.B),Mirror(t.A),t.Material));var mirrorSource=BomPrismClipper.Prepare(mirrored.ToArray(),2);Check(mirrorSource.Failure==null,"mirrored source "+mirrorSource.Failure);var mirrorCut=BomPrismClipper.Build(mirrorSource,new[]{new Vector2(7,-10),new Vector2(10,-10),new Vector2(10,10),new Vector2(7,10)});Check(mirrorCut.Supported,"mirrored cut "+mirrorCut.Reason);Check(Math.Abs(Volume(mirrorCut)-4.8)<.0002,"mirrored volume "+Volume(mirrorCut));foreach(var t in mirrorCut.Exterior)foreach(var v in new[]{t.A,t.B,t.C}){float x=(7-v.Position.x)/2,y=(v.Position.y+2)/3,z=(v.Position.z-4)/.4f;Check(Math.Abs(v.UV1.x-x)<.00001&&Math.Abs(v.UV1.y-y)<.00001&&Math.Abs(v.UV2.z-z*2)<.00001&&Math.Abs(v.UV7.x-x*7)<.00001&&Math.Abs(v.UV7.w-7)<.00001,"interpolated vertex channels");Check(Math.Abs(v.Color.r-(x+2)/4)<.00001&&Math.Abs(v.Tangent.w+1)<.00001,"color or mirrored tangent handedness");if(t.Material==0)Check(Math.Abs(v.UV0.x-x-8)<.00001&&Math.Abs(v.UV0.y-y-2)<.00001,"mirrored exterior UV mapping");}Console.WriteLine("PASS mirrored nonuniform transform, UV channels, color and tangent handedness volume="+Volume(mirrorCut));
  var lower=Source(new[]{new Vector2(-2,-2),new Vector2(2,-2),new Vector2(2,0),new Vector2(-2,0)});var upper=Source(new[]{new Vector2(-2.5f,-1),new Vector2(2.5f,-1),new Vector2(2.5f,1),new Vector2(-2.5f,1)},1.2f);var layers=new List<BomClipTriangle>(lower.Triangles);layers.AddRange(upper.Triangles);var layered=BomPrismClipper.Prepare(layers.ToArray(),2);Check(layered.Failure==null&&layered.ComponentCount==2,"layered source components");var upperCell=BomPrismClipper.Build(layered,new[]{new Vector2(-.5f,0),new Vector2(.5f,0),new Vector2(.5f,.5f),new Vector2(-.5f,.5f)});Check(upperCell.Supported&&Math.Abs(Volume(upperCell)-.6)<.0001,"a tangent layer must not invalidate the occupied visual layer: "+upperCell.Reason);var overlapCell=BomPrismClipper.Build(layered,new[]{new Vector2(-.5f,-.5f),new Vector2(.5f,-.5f),new Vector2(.5f,0),new Vector2(-.5f,0)});Check(overlapCell.Supported&&Math.Abs(Volume(overlapCell)-1.1)<.0001,"overlapping closed layers require independent solid caps: "+overlapCell.Reason);Console.WriteLine("PASS layered solid groups, tangent component omission and independent cap loops");
  var open=BomPrismClipper.Prepare(new[]{a.Triangles[0]},2);Check(open.Failure!=null&&!BomPrismClipper.Build(open,new[]{Vector2.zero,Vector2.right,Vector2.one}).Supported,"open source must declare fallback");Console.WriteLine("PASS open source explicit fallback: "+open.Failure);
  var tube=new List<BomClipTriangle>();
  BomClipVertex V(Vector3 p,Vector3 n)=>new BomClipVertex{Position=p,Normal=n,Tangent=new Vector4(0,1,0,1),Color=Color.white,UV0=new Vector4(p.y,p.z,0,0)};
  void Quad(Vector3 p,Vector3 q,Vector3 r,Vector3 t,Vector3 n){if(Vector3.Dot(Vector3.Cross(q-p,r-p),n)<0){var swap=q;q=t;t=swap;}tube.Add(new BomClipTriangle(V(p,n),V(q,n),V(r,n),0));tube.Add(new BomClipTriangle(V(p,n),V(r,n),V(t,n),0));}
  Vector3 P(float x,Vector2 yz)=>new Vector3(x,yz.x,yz.y);
  var outer=new[]{new Vector2(-2,-2),new Vector2(2,-2),new Vector2(2,2),new Vector2(-2,2)};var inner=new[]{new Vector2(-1,-1),new Vector2(1,-1),new Vector2(1,1),new Vector2(-1,1)};
  for(int i=0;i<4;i++){int j=(i+1)%4;var edge=outer[j]-outer[i];var n=new Vector3(0,edge.y,-edge.x).normalized;Quad(P(-2,outer[i]),P(2,outer[i]),P(2,outer[j]),P(-2,outer[j]),n);Quad(P(-2,inner[i]),P(2,inner[i]),P(2,inner[j]),P(-2,inner[j]),-n);Quad(P(-2,outer[i]),P(-2,outer[j]),P(-2,inner[j]),P(-2,inner[i]),Vector3.left);Quad(P(2,outer[i]),P(2,outer[j]),P(2,inner[j]),P(2,inner[i]),Vector3.right);}
  var hollow=BomPrismClipper.Prepare(tube.ToArray(),1);Check(hollow.Failure==null,"hollow source "+hollow.Failure);var half=BomPrismClipper.Build(hollow,new[]{new Vector2(0,-3),new Vector2(3,-3),new Vector2(3,3),new Vector2(0,3)});Check(half.Supported,"cap with hole: "+half.Reason);Check(Math.Abs(Volume(half)-24)<.0001,"hollow cap volume "+Volume(half));foreach(var cap in half.Caps)foreach(var t in cap.Triangles){var center=(t.A.Position+t.B.Position+t.C.Position)/3;Check(Math.Abs(center.y)>=.99999||Math.Abs(center.z)>=.99999,"cap filled a source hole");}Console.WriteLine("PASS closed hollow solid preserves cap hole volume="+Volume(half));
  var quarter=BomPrismClipper.Build(hollow,new[]{new Vector2(0,0),new Vector2(3,0),new Vector2(3,3),new Vector2(0,3)});Check(quarter.Supported,"intersecting hollow cut planes: "+quarter.Reason);Check(Math.Abs(Volume(quarter)-12)<.0001,"hollow quarter volume "+Volume(quarter));Console.WriteLine("PASS intersecting hollow cap planes volume="+Volume(quarter));
  var cancelled=new CancellationTokenSource();cancelled.Cancel();var obsolete=BomPrismClipper.Build(hollow,new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up},cancelled.Token);Check(!obsolete.Supported&&obsolete.Reason.Contains("cancelled"),"cancelled worker must not return applicable geometry");Console.WriteLine("PASS cancelled geometry request");
 }
